import React, {useEffect, useMemo, useRef, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {invoke,watchSnapshots,desktop,APP_VERSION} from './transport';
import {RemoteSettings} from './RemoteSettings';
import {Activity,LayoutDashboard,GanttChartSquare,Cpu,BarChart3,Settings2,ListChecks,Monitor,ArrowUpRight,Check,Clock,AlertTriangle,Search,Sun,Moon,ChevronDown,ChevronRight,X,Link2,ExternalLink,Copy,FolderOpen,ShieldCheck,GitBranch,Command,Wifi,RefreshCw,CheckCircle2,Circle,Terminal,FileCode2,Zap,Download,Archive,ArchiveRestore} from 'lucide-react';
import type {Agent,Snapshot,Event,Detail,Task,MonitorTask,Analytics,Process,SourceHealth,ChatRequest} from './types';
import './styles.css';
import './mobile.css';

type Page='overview'|'timeline'|'processes'|'usage'|'tasks'|'settings';
type Notify=(message:string)=>void;
const nav=[['overview','工作总览',LayoutDashboard],['timeline','时间线',GanttChartSquare],['processes','系统进程',Cpu],['usage','用量与历史',BarChart3],['tasks','任务看板',ListChecks],['settings','连接与设置',Settings2]] as const;
const labels:Record<string,string>={RUNNING:'执行中',WAITING_MODEL:'等待模型',WAITING_TOOL:'工具运行中',WAITING_USER:'等待确认',IDLE:'空闲',COMPLETED:'已完成',FAILED:'失败',CRASHED:'进程已退出',SUSPECTED_STALLED:'疑似停滞',UNKNOWN:'未知'};
const live=new Set(['RUNNING','WAITING_MODEL','WAITING_TOOL','WAITING_USER']);
const activeTurn=(s?:string)=>['inProgress','in_progress','running','started'].includes(s||'');
const compact=(n:number|null|undefined)=>n==null?'—':Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:2}).format(n);
const full=(n:number|null|undefined)=>n==null?'unknown':n.toLocaleString('en-US');
const short=(s?:string|null,n=8)=>s?s.slice(0,n):'unknown';
const stamp=(ms?:number|null)=>ms?new Date(ms).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'unknown';
const clock=(ms:number)=>new Date(ms).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
function duration(ms?:number|null){if(ms==null)return '—';let s=Math.max(0,Math.floor(ms/1000));if(s<60)return `${s}s`;let m=Math.floor(s/60);if(m<60)return `${m}m ${s%60}s`;let h=Math.floor(m/60);if(h<24)return `${h}h ${m%60}m`;return `${Math.floor(h/24)}d ${h%24}h`;}
function ago(at:number,now:number){const s=Math.max(0,Math.floor((now-at)/1000));return s<5?'刚刚':s<60?`${s} 秒前`:s<3600?`${Math.floor(s/60)} 分钟前`:s<86400?`${Math.floor(s/3600)} 小时前`:`${Math.floor(s/86400)} 天前`;}
function tone(status:string){return ['FAILED','CRASHED'].includes(status)?'red':status==='SUSPECTED_STALLED'?'orange':['WAITING_TOOL','WAITING_USER'].includes(status)?'amber':['RUNNING','WAITING_MODEL'].includes(status)?'green':status==='COMPLETED'?'muted-green':'gray';}
function recent(a:Agent,now:number){if(a.archived||now-a.lastActivityMs>86400000)return false;return a.lastActivityMs>now-86400000||live.has(a.status)||a.status==='SUSPECTED_STALLED'||a.status==='CRASHED'||activeTurn(a.turn?.status);}
function Status({status,code=false}:{status:string;code?:boolean}){return <span className={`status ${tone(status)}`} title={status}><i className={live.has(status)?'pulse':''}/>{code?status:(labels[status]||status)}</span>}
function IconButton({children,label,onClick}:{children:React.ReactNode;label:string;onClick:()=>void}){return <button type="button" className="icon-button" title={label} aria-label={label} onClick={onClick}>{children}</button>}
function Empty({title,children}:{title:string;children?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><Activity size={27}/></div><h3>{title}</h3><p>{children}</p></div>}
function Field({label,value,mono=false}:{label:string;value:React.ReactNode;mono?:boolean}){return <div className="field"><dt>{label}</dt><dd className={mono?'mono':''}>{value??<span className="unknown">unknown</span>}</dd></div>}
async function action(command:string,args:Record<string,unknown>,notify:Notify,message='已更新'){try{await invoke(command,args);notify(message);}catch(e){notify(String(e));}}

function App(){
 const [data,setData]=useState<Snapshot>({loading:true,stale:false,agents:[],processes:[],tasks:[],bindings:[]});
 const [page,setPage]=useState<Page>('overview'),[query,setQuery]=useState(''),[scope,setScope]=useState('recent'),[selected,setSelected]=useState<string|null>(null),[binding,setBinding]=useState<Agent|null>(null),[now,setNow]=useState(Date.now()),[toast,setToast]=useState('');
 const [theme,setTheme]=useState(localStorage.getItem('agent-monitor-theme')||'dark');const search=useRef<HTMLInputElement>(null);
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('agent-monitor-theme',theme)},[theme]);
 useEffect(()=>{const t=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(t)},[]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>watchSnapshots(v=>setData(v),reason=>setData(d=>({...d,loading:false,stale:true,collectorError:reason}))),[]);
 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'){setBinding(null);setSelected(null)}if(e.key==='/'&&!(e.target instanceof HTMLInputElement)&&!(e.target instanceof HTMLTextAreaElement)){e.preventDefault();search.current?.focus()}if(e.ctrlKey&&e.key==='1'){e.preventDefault();setPage('overview')}if(e.ctrlKey&&e.key==='2'){e.preventDefault();setPage('timeline')}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[]);
 const stale=data.stale||!!data.generatedAt&&now-data.generatedAt>15000;
 const selectedAgent=data.agents.find(a=>a.id===selected)||null;
 const setArchived=async(a:Agent,archived:boolean)=>{try{await invoke('set_agent_archived',{id:a.id,archived});setData(d=>({...d,agents:d.agents.map(x=>x.id===a.id?{...x,archived,archivedAt:archived?Date.now():null}:x)}));setToast(archived?'已归档：仍保留原始失败/停滞证据，但不再计入“需留意”。':'已恢复到工作列表。');if(archived&&selected===a.id)setSelected(null);}catch(e){setToast(String(e))}};
 const visible=useMemo(()=>data.agents.filter(a=>{const match=`${a.title} ${a.project} ${a.cwd} ${a.id} ${a.model} ${a.binding?.title||''} ${a.binding?.conversationId||''} ${a.acpSessions?.map(s=>s.id).join(' ')}`.toLowerCase().includes(query.toLowerCase());const fresh=now-a.lastActivityMs<=86400000;return match&&(scope==='all'||scope==='recent'&&recent(a,now)||scope==='active'&&!a.archived&&fresh&&live.has(a.status)||scope==='attention'&&!a.archived&&fresh&&['SUSPECTED_STALLED','FAILED','CRASHED','WAITING_USER'].includes(a.status))}),[data.agents,query,scope,Math.floor(now/10000)]);
 const current=data.agents.filter(a=>recent(a,now));
 const requests=data.requests||[];
 const visibleRequests=useMemo(()=>requests.filter(r=>{const match=`${r.prompt} ${r.conversationTitle} ${r.project} ${r.id} ${r.agentdockTaskId||''}`.toLowerCase().includes(query.toLowerCase());const fresh=r.startedAt>now-86400000;const active=['active','responding'].includes(r.status);const attention=(r.progressProtocol==='unclaimed'&&r.tools.length>0)||(active&&now-(r.lastActivityMs||r.updatedAt)>10*60*1000);return match&&(scope==='all'||scope==='recent'&&fresh||scope==='active'&&active||scope==='attention'&&attention)}),[requests,query,scope,Math.floor(now/10000)]);
 const metrics=[{label:'ACTIVE',name:'正在进行',value:current.filter(a=>['RUNNING','WAITING_MODEL'].includes(a.status)).length,tone:'green',scope:'active'},{label:'WAITING',name:'工具 / 用户',value:current.filter(a=>['WAITING_TOOL','WAITING_USER'].includes(a.status)).length,tone:'amber',scope:'active'},{label:'STALLED',name:'需要留意',value:current.filter(a=>a.status==='SUSPECTED_STALLED').length,tone:'orange',scope:'attention'},{label:'FAILED',name:'失败 / 退出',value:current.filter(a=>['FAILED','CRASHED'].includes(a.status)).length,tone:'red',scope:'attention'}];
 const dockHealthy=data.sources?.agentdock?.healthy;
 return <div className={`shell ${selectedAgent?'has-detail':''}`}>
  <aside className="sidebar"><div className="brand"><div className="brand-icon"><Activity size={23}/></div><div><strong>Agent Monitor</strong><span>YOUR LOCAL CONTROL ROOM</span></div></div><div className="workspace"><span className="workspace-dot"/><div>{desktop?'这台电脑':'家里的电脑'}<small>{desktop?'Windows · Local first':'Web · Remote monitor'}</small></div><Monitor size={16}/></div><div className="nav-label">WORKSPACE</div><nav>{nav.map(([id,label,Icon])=>{const activeRequests=(data.requests||[]).filter(r=>['active','responding'].includes(r.status)).length;const activeTasks=activeRequests||((data.monitorTasks||[]).filter(t=>t.status==='active').length+data.tasks.filter(t=>t.status==='active').length);return <button key={id} aria-label={label} className={page===id?'nav-item selected':'nav-item'} onClick={()=>{setPage(id);setSelected(null)}}><Icon size={18}/><span>{label}</span>{id==='tasks'&&activeTasks>0&&<b>{activeTasks}</b>}</button>})}</nav><div className="sidebar-note"><ShieldCheck size={18}/><span>{desktop?'源数据保留在本机':'源文件留在家里'}<small>本机采集 · 受保护的远程查看</small></span></div><footer><div className="collector-state"><i className={stale?'error':data.loading?'starting':'online'}/><span>{stale?'采集暂不可用':data.loading?'正在连接真实数据':'实时采集已连接'}</span></div><small>{data.collectionMs!=null?`${data.collectionMs} ms / cycle`:'initializing'}<span>v{APP_VERSION}</span></small></footer></aside>
  <div className="workspace-main"><header className="topbar"><div className="breadcrumb">Workspace <ChevronRight size={13}/> <strong>{nav.find(n=>n[0]===page)?.[1]}</strong></div><div className="top-actions"><span className={`connection-pill ${dockHealthy?'good':''}`}><i/>AgentDock {dockHealthy?'Healthy':dockHealthy===false?'Unavailable':'…'}</span><IconButton label={theme==='dark'?'切换亮色':'切换暗色'} onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</IconButton></div></header>
   <main className="page"><div className="page-heading"><div><div className="eyebrow">{page==='overview'?'ALL YOUR AGENTS. ONE CLEAR PICTURE.':page==='timeline'?'FOLLOW THE WORK, NOT THE SPINNER.':page==='tasks'?'GOALS OVER PROCESSES.':page==='settings'?'CONNECTED, NOT ASSUMED.':'LOCAL OBSERVABILITY'}</div><h1>{nav.find(n=>n[0]===page)?.[1]}{page==='overview'&&<span className={`live-label ${stale?'offline':''}`}><i/>{stale?'OFFLINE':'LIVE'}</span>}</h1><p>{page==='overview'?'谁发起了工作，正在做什么，哪里需要你留意。':page==='timeline'?'把 conversation、ACP、turn 与工具活动放回同一条时间轴。':page==='processes'?'系统进程是运行载体，不是逻辑 Agent。':page==='usage'?'真实累计值与连续观测增量分开记账。':page==='tasks'?'按项目 → 对话 → 每条用户 Request 查看步骤、动态计划与真实执行。':'只读采集、精确归属，以及清楚可见的能力边界。'}</p></div><span className="today">{new Date(now).toLocaleDateString('en-GB',{day:'2-digit',month:'short'})}<small>{clock(now)}</small></span></div>
    {stale&&<div className="notice danger" role="alert"><AlertTriangle size={19}/><div><strong>当前数据可能已过期</strong><p>{data.collectorError||'未收到新的采集快照。界面不会把旧状态当作实时结果。'} 最近成功采集：{stamp(data.generatedAt)}</p>{!desktop&&<button className="secondary" onClick={()=>location.reload()}>重新连接 / 登录</button>}</div></div>}
    {!data.loading&&data.sources?.progressPolicy?.healthy===false&&<div className="notice danger" role="alert"><AlertTriangle size={19}/><div><strong>执行进度规则未激活</strong><p>Agent Monitor 仍会记录 Request 与真实工具活动，但 LLM 可能不会主动创建/更新 task_manage 步骤。请在“连接与设置”检查 execution-progress Skill。</p></div></div>}
    {data.loading?<Empty title="正在连接你的真实工作流">读取 AgentDock / Codex 数据并核验进程关系。首次读取会比之后的增量更新慢。</Empty>:<>
    {(page==='overview'||page==='timeline')&&<><section className="metrics">{metrics.map(m=><button key={m.label} className="metric" onClick={()=>{setScope(m.scope);setPage('overview')}}><div className="metric-label"><i className={m.tone}/>{m.label}</div><strong>{m.value}</strong><span>{m.name}</span></button>)}<div className="metric token-metric"><div className="metric-label"><Zap size={13}/>TOKENS TODAY · OBSERVED</div><strong>{compact(data.stats?.observedTokensToday)}</strong><span>仅连续观测增量，不是历史总量</span></div></section><div className="metric-caption">当前工作与最近 24 小时记录 · 未结束的历史 turn 单独保留异常提示</div></>}
    {page==='overview'&&<><div className="overview-timeline"><GlobalTimeline agents={data.agents} monitorTasks={data.monitorTasks||[]} now={now} onSelect={setSelected}/></div>{requests.length>0&&<RequestWorklist requests={visibleRequests} agents={data.agents} now={now} onSelect={setSelected}/>}<div className="toolbar"><div className="segmented">{[['recent','当前 / 近 24h'],['active','运行中'],['attention','需留意'],['all','全部记录']].map(([v,l])=><button key={v} className={scope===v?'chosen':''} onClick={()=>setScope(v)}>{l}</button>)}</div><label className="search"><Search size={16}/><input ref={search} aria-label="搜索工作" value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索对话、项目、模型…"/><kbd>/</kbd></label></div>
    {current.some(a=>a.source==='AgentDock ACP'&&!a.binding)&&<div className="notice attribution"><Link2 size={19}/><div><strong>让工作找到它的发起对话</strong><p>ACP → Codex 已精确匹配。没有 conversation 证据的运行保留为“未归属”，不会按时间或共享 parent 目录猜测。</p></div><button className="text-button" onClick={()=>setPage('settings')}>启用自动归属 <ArrowUpRight size={15}/></button></div>}
    <ConversationList agents={visible} monitorTasks={data.monitorTasks||[]} now={now} onSelect={setSelected} onBind={setBinding} onArchive={setArchived}/><div className="footnote">已读取 {full(data.sources?.codex?.threadCount)} 个 Codex thread 元数据；当前监控集合 {data.agents.length} 个逻辑工作，ACP 别名不会重复累计 token。点击工作查看证据。</div></>}
    {page==='timeline'&&<GlobalTimeline agents={data.agents} monitorTasks={data.monitorTasks||[]} now={now} onSelect={setSelected}/>}
    {page==='processes'&&<ProcessPage processes={data.processes} agents={data.agents}/>}
    {page==='usage'&&<UsagePage snapshot={data} notify={setToast}/>}
    {page==='tasks'&&<><RequestWorklist requests={requests} agents={data.agents} now={now} onSelect={setSelected} taskPage/><TaskBoard monitorTasks={data.monitorTasks||[]} nativeTasks={data.tasks} agents={data.agents} now={now} onSelect={setSelected} reaper={data.sources?.autoStop}/></>}
    {page==='settings'&&(desktop?<SettingsPage snapshot={data} notify={setToast}/>:<RemoteSettings snapshot={data} notify={setToast}/>)}
    </>}
   </main>
  </div>
  <nav className="mobile-nav" aria-label="手机导航">{nav.map(([id,label,Icon],i)=><button key={id} className={page===id?'selected':''} aria-label={label} onClick={()=>{setPage(id);setSelected(null)}}><Icon size={21}/><span>{['总览','时间线','进程','用量','任务','连接'][i]}</span></button>)}</nav>
  {selectedAgent&&<AgentDetail agent={selectedAgent} tasks={data.tasks} now={now} onClose={()=>setSelected(null)} onBind={()=>setBinding(selectedAgent)} onSelect={setSelected} onArchive={setArchived} notify={setToast}/>}
  {binding&&<BindModal agent={binding} onClose={()=>setBinding(null)} notify={setToast}/>}
  {toast&&<div className="toast" role="status"><CheckCircle2 size={17}/><span>{toast}</span><button onClick={()=>setToast('')} aria-label="关闭提示"><X size={15}/></button></div>}
 </div>
}

function monitorTaskForAgent(a:Agent,tasks:MonitorTask[]){return tasks.filter(t=>t.agentIds?.includes(a.id)).sort((x,y)=>(y.updatedAt||0)-(x.updatedAt||0))[0]}
function workGroup(a:Agent,tasks:MonitorTask[]){
 const mt=monitorTaskForAgent(a,tasks),native=a.task;
 const taskId=mt?.id||native?.id||'no-task',taskTitle=mt?.title||native?.title||'';
 const conversationKey=a.binding?.conversationId||(a.source==='AgentDock ACP'?'unattributed-acp':'codex-local');
 const conversationTitle=a.binding?(a.binding.title||`ChatGPT 对话 · ${short(a.binding.conversationId)}`):a.source==='AgentDock ACP'?'未归属的 AgentDock 工作':'本机 Codex 工作';
 return {key:`${conversationKey}:${taskId}`,title:taskTitle||conversationTitle,subtitle:taskTitle?`${conversationTitle} · ${mt?'自动任务':'AgentDock Task'}`:conversationTitle,kind:a.binding?'conversation':a.source==='AgentDock ACP'?'unassigned':'local'};
}
function ConversationList({agents,monitorTasks,now,onSelect,onBind,onArchive}:{agents:Agent[];monitorTasks:MonitorTask[];now:number;onSelect:(id:string)=>void;onBind:(a:Agent)=>void;onArchive:(a:Agent,archived:boolean)=>void}){
 const [collapsedProjects,setCollapsedProjects]=useState<Record<string,boolean>>({}),[expandedGroups,setExpandedGroups]=useState<Record<string,boolean>>({});
 const projects=useMemo(()=>{const map=new Map<string,Map<string,{title:string;subtitle:string;kind:string;agents:Agent[]}>>();for(const a of agents){const project=a.project||'unknown',g=workGroup(a,monitorTasks);if(!map.has(project))map.set(project,new Map());const groups=map.get(project)!;if(!groups.has(g.key))groups.set(g.key,{title:g.title,subtitle:g.subtitle,kind:g.kind,agents:[]});groups.get(g.key)!.agents.push(a);}return [...map.entries()].map(([project,groups])=>({project,groups:[...groups.entries()].map(([key,value])=>({key,...value})).sort((a,b)=>Math.max(...b.agents.map(x=>x.lastActivityMs))-Math.max(...a.agents.map(x=>x.lastActivityMs))),count:[...groups.values()].reduce((n,g)=>n+g.agents.length,0),latest:Math.max(...[...groups.values()].flatMap(g=>g.agents.map(a=>a.lastActivityMs)))})).sort((a,b)=>b.latest-a.latest)},[agents,monitorTasks]);
 if(!projects.length)return <Empty title="这个视图下没有工作">试试“全部记录”，或更改搜索条件。</Empty>;
 return <div className="project-agent-list">{projects.map(p=>{const collapsed=collapsedProjects[p.project]??false;return <section className="project-agent-card" key={p.project}><button className="project-agent-heading" onClick={()=>setCollapsedProjects(s=>({...s,[p.project]:!collapsed}))}><span className="project-folder"><FolderOpen size={18}/></span><div><strong>{p.project}</strong><small>{p.groups.length} 个对话 / 任务 · {p.count} Agents · 最近 {ago(p.latest,now)}</small></div><span className="count-badge">{p.count}</span><ChevronDown size={16} className={collapsed?'collapsed-chevron':''}/></button>{!collapsed&&<div className="project-agent-body">{p.groups.map(g=>{const expanded=expandedGroups[`${p.project}:${g.key}`]??false,rows=expanded?g.agents:[];return <section className={`conversation-card nested ${g.kind}`} key={g.key}><button className="work-group-heading" onClick={()=>setExpandedGroups(s=>({...s,[`${p.project}:${g.key}`]:!expanded}))}><div className="conversation-avatar">{g.kind==='conversation'?<Command size={18}/>:g.kind==='unassigned'?<Link2 size={17}/>:<Monitor size={17}/>}</div><div className="conversation-title"><h2>{g.title}<span className="count-badge">{g.agents.length}</span></h2><p>{g.subtitle}</p></div><ChevronDown size={15} className={expanded?'':'collapsed-chevron'}/></button>{expanded&&<><div className="agent-column-labels"><span>AGENT</span><span>模型与当前活动</span><span>TOKENS / TURN</span><span/></div>{rows.map(a=>{const parentInGroup=g.agents.some(x=>x.id===a.parentThreadId);return <div className={`agent-row ${parentInGroup?'child-agent':''} ${a.archived?'archived':''}`} key={a.id}><button className="agent-main" onClick={()=>onSelect(a.id)}><div className="agent-identity"><div className={`agent-indicator ${tone(a.status)}`}>{parentInGroup?<GitBranch size={16}/>:<Activity size={16}/>}</div><div><strong title={a.title}>{a.title}</strong><span>{a.acpSessions?.length?`ACP ${short(a.acpSessions[0].id.replace('acps_',''),6)}`:short(a.id)}</span></div></div><div className="agent-activity"><strong>{a.model||'unknown model'} <em>{a.reasoningEffort||'unknown effort'}</em></strong><span title={a.currentTool?.command||a.lastCommand||''}>{a.task?.steps.find(s=>s.status==='in_progress')?.title||a.currentTool?.name||(a.status==='COMPLETED'?`最近：${a.lastTool?.name||'turn completed'}`:labels[a.status]||a.status)}</span><Status status={a.status}/>{a.archived&&<span className="archived-label">已归档</span>}</div><div className="agent-numbers"><strong title={`${full(a.tokensUsed)} · thread 累计`}>{compact(a.tokensUsed)}<small> tokens</small></strong><span>{a.turn?duration(a.turn.durationMs??(activeTurn(a.turn.status)?now-a.turn.startMs:null)):'—'}<b>·</b>{ago(a.lastActivityMs,now)}</span></div></button><div className="agent-end">{a.archived?<button className="row-action restore" title="恢复到工作列表" onClick={()=>onArchive(a,false)}><ArchiveRestore size={14}/>恢复</button>:['SUSPECTED_STALLED','FAILED','CRASHED','WAITING_USER'].includes(a.status)?<button className="row-action" title="保留原始状态，但从需留意中移除" onClick={()=>onArchive(a,true)}><Archive size={14}/>归档</button>:!a.binding&&a.source==='AgentDock ACP'?<IconButton label="手动绑定网页对话（自动归属失败时兜底）" onClick={()=>onBind(a)}><Link2 size={16}/></IconButton>:<ChevronRight size={16}/>}</div></div>})}<button className="show-more" onClick={()=>setExpandedGroups(s=>({...s,[`${p.project}:${g.key}`]:false}))}>收起 {g.agents.length} 个 Agent<ChevronDown size={14}/></button></>}</section>})}</div>}</section>})}</div>
}

function RequestWorklist({requests,agents,now,onSelect,taskPage=false}:{requests:ChatRequest[];agents:Agent[];now:number;onSelect:(id:string)=>void;taskPage?:boolean}){
 const [collapsedProjects,setCollapsedProjects]=useState<Record<string,boolean>>({}),[collapsedConversations,setCollapsedConversations]=useState<Record<string,boolean>>({}),[expandedRequests,setExpandedRequests]=useState<Record<string,boolean>>({});
 const projects=useMemo(()=>{const map=new Map<string,Map<string,{title:string;requests:ChatRequest[]}>>();for(const r of requests){const project=r.project||'unknown',cid=r.conversationId||'unknown';if(!map.has(project))map.set(project,new Map());const conversations=map.get(project)!;if(!conversations.has(cid))conversations.set(cid,{title:r.conversationTitle||`ChatGPT 对话 · ${short(cid)}`,requests:[]});conversations.get(cid)!.requests.push(r);}return [...map.entries()].map(([project,conversations])=>({project,conversations:[...conversations.entries()].map(([conversationId,value])=>({conversationId,title:value.title,requests:value.requests.sort((a,b)=>b.startedAt-a.startedAt),latest:Math.max(...value.requests.map(r=>r.lastActivityMs||r.updatedAt||r.startedAt))})).sort((a,b)=>b.latest-a.latest),count:[...conversations.values()].reduce((n,c)=>n+c.requests.length,0),latest:Math.max(...[...conversations.values()].flatMap(c=>c.requests.map(r=>r.lastActivityMs||r.updatedAt||r.startedAt)))})).sort((a,b)=>b.latest-a.latest)},[requests]);
 if(!projects.length)return taskPage?<Empty title="还没有捕获到 Request">更新浏览器扩展并刷新 ChatGPT 后，每条用户消息都会进入这里；执行型 Request 会继续关联 Task、步骤与工具活动。</Empty>:<Empty title="这个筛选下没有 Request">可以切换到“全部记录”查看较早请求。</Empty>;
 return <div className={`request-worklist ${taskPage?'task-page':''}`}>{taskPage&&<section className="panel request-board-summary"><div><span className="eyebrow">PROJECT → CONVERSATION → REQUEST → STEPS → EXECUTION</span><h2>用户请求进度</h2><p>每条 ChatGPT 用户消息是一条 Request。执行型 Request 由 LLM 认领 Task 和步骤；计划中途变化时，新建的补充计划段会合并到同一 Request。</p></div><span className="proof-badge connected"><Activity size={14}/>动态计划</span></section>}{projects.map(p=>{const projectCollapsed=collapsedProjects[p.project]??false;return <section className="project-agent-card request-project" key={p.project}><button className="project-agent-heading" onClick={()=>setCollapsedProjects(x=>({...x,[p.project]:!projectCollapsed}))}><span className="project-folder"><FolderOpen size={18}/></span><div><strong>{p.project}</strong><small>{p.conversations.length} 个对话 · {p.count} Requests · 最近 {ago(p.latest,now)}</small></div><span className="count-badge">{p.count}</span><ChevronDown size={16} className={projectCollapsed?'collapsed-chevron':''}/></button>{!projectCollapsed&&<div className="request-project-body">{p.conversations.map(c=>{const ckey=`${p.project}:${c.conversationId}`,conversationCollapsed=collapsedConversations[ckey]??false;return <section className="request-conversation" key={c.conversationId}><button className="request-conversation-heading" onClick={()=>setCollapsedConversations(x=>({...x,[ckey]:!conversationCollapsed}))}><span className="conversation-avatar"><Command size={17}/></span><div><strong>{c.title}</strong><small>{short(c.conversationId,18)} · {c.requests.length} Requests</small></div><ChevronDown size={15} className={conversationCollapsed?'collapsed-chevron':''}/></button>{!conversationCollapsed&&<div className="request-list">{c.requests.map(r=>{const rkey=`${c.conversationId}:${r.id}`,plans=r.plans?.length?r.plans:r.plan?[r.plan]:[],rev=r.progress?.revisionCount??Math.max(0,plans.length-1),done=r.progress?.completed||0,total=r.progress?.total||0,active=['active','responding'].includes(r.status),expanded=expandedRequests[rkey]??active,linked=r.agentIds.map(id=>agents.find(a=>a.id===id)).filter((a):a is Agent=>!!a),title=r.prompt.split(/\s+/).join(' ').trim(),pct=total?Math.round(done/total*100):0;return <section className={`request-card ${active?'active':''} protocol-${r.progressProtocol}`} key={r.id}><button className="request-heading" onClick={()=>setExpandedRequests(x=>({...x,[rkey]:!expanded}))}><span className="request-time"><Clock size={13}/><time>{clock(r.startedAt).slice(0,5)}</time></span><div className="request-copy"><strong title={r.prompt}>{title.length>96?`${title.slice(0,96)}…`:title||'空白请求'}</strong><small>{r.status==='active'?'执行中':r.status==='responding'?'正在回答':'已完成'} · 最近 {ago(r.lastActivityMs||r.updatedAt,now)}{r.agentdockTaskId?` · ${short(r.agentdockTaskId,14)}`:''}</small></div><div className="request-progress-brief">{r.progressProtocol==='claimed'?<><b>{done}<small> / {total}</small></b><i><span style={{width:`${pct}%`}}/></i>{r.progress?.currentStep&&<span className="current-step" title={r.progress.currentStep}>当前：{r.progress.currentStep}</span>}{rev>0&&<em>+{rev} 次计划修订</em>}</>:r.progressProtocol==='unclaimed'?<span className="protocol-warning">未认领计划</span>:active?<span className="protocol-muted">等待执行计划</span>:<span className="protocol-muted">无执行计划</span>}</div><ChevronDown size={15} className={expanded?'':'collapsed-chevron'}/></button>{expanded&&<div className="request-detail"><p className="request-prompt">{r.prompt}</p>{r.progressProtocol==='unclaimed'&&r.tools.length>0&&<div className="notice request-warning"><AlertTriangle size={16}/><p>已经观察到 AgentDock 执行，但当前 Request 尚未通过 task_manage 声明步骤。执行证据仍会记录；这条状态会在计划被认领后自动消失。</p></div>}{plans.length>0&&<div className="request-plans">{plans.map((plan,pi)=><section className="plan-segment" key={plan.id}><header><div><span>{pi===0?'初始计划':`计划修订 ${pi}`}</span><strong>{plan.title}</strong></div><span className={`plan-state ${plan.status}`}>{plan.status==='active'?'进行中':'已完成'}</span></header><div className="request-steps">{plan.steps.map((step,si)=><div className={step.status} key={`${plan.id}:${step.id}`}><span className="step-mark">{step.status==='completed'?<CheckCircle2 size={15}/>:step.status==='in_progress'?<span className="step-pulse"/>:<Circle size={15}/>}</span><b>{si+1}</b><span>{step.title}</span></div>)}</div></section>)}</div>}{r.tools.length>0&&<section className="request-execution"><h3>AgentDock 执行</h3>{r.tools.slice(-16).map(t=><div className="request-tool" key={t.invocationId}><span className={`tool-state ${t.status}`}/><div><strong>{t.toolName.replace(/^AgentDock\./,'')}</strong><small>{t.action||'call'}{t.finishedAt?` · ${duration(t.finishedAt-t.startedAt)}`:' · 运行中'}</small></div>{t.taskId&&<code>{short(t.taskId,14)}</code>}</div>)}</section>}{linked.length>0&&<section className="request-agents"><h3>关联 Agent</h3><div>{linked.map(a=><button key={a.id} onClick={()=>onSelect(a.id)}><Activity size={13}/><span>{a.title}</span><Status status={a.status}/><ChevronRight size={13}/></button>)}</div></section>}<p className="fine-print">Request ID · <code>{short(r.id,22)}</code> · User message · <code>{short(r.userMessageId,22)}</code></p></div>}</section>})}</div>}</section>})}</div>}</section>})}</div>
}

function GlobalTimeline({agents,monitorTasks,now,onSelect}:{agents:Agent[];monitorTasks:MonitorTask[];now:number;onSelect:(id:string)=>void}){
 const [hours,setHours]=useState(1),[collapsedProjects,setCollapsedProjects]=useState<Record<string,boolean>>({}),[expandedGroups,setExpandedGroups]=useState<Record<string,boolean>>({});const end=now,start=end-hours*3600000;
 const rows=agents.filter(a=>!a.archived&&now-a.lastActivityMs<=86400000&&a.turn&&(a.turn.endMs||now)>start&&a.turn.startMs<end).slice(0,150);
 const projects=useMemo(()=>{const map=new Map<string,Map<string,Agent[]>>();for(const a of rows){const project=a.project||'unknown',g=workGroup(a,monitorTasks);if(!map.has(project))map.set(project,new Map());const groups=map.get(project)!;if(!groups.has(g.key))groups.set(g.key,[]);groups.get(g.key)!.push(a);}return [...map.entries()].map(([project,groups])=>({project,groups:[...groups.entries()].map(([key,items])=>({key,meta:workGroup(items[0],monitorTasks),agents:items,start:Math.min(...items.map(a=>a.turn!.startMs)),end:Math.max(...items.map(a=>a.turn!.endMs||now)),latest:Math.max(...items.map(a=>a.lastActivityMs))})).sort((a,b)=>b.latest-a.latest),count:[...groups.values()].reduce((n,x)=>n+x.length,0),latest:Math.max(...[...groups.values()].flatMap(x=>x.map(a=>a.lastActivityMs)))})).sort((a,b)=>b.latest-a.latest)},[rows,monitorTasks,Math.floor(now/10000)]);
 const ticks=Array.from({length:5},(_,i)=>end-(end-start)*i/4);
 return <section className="panel timeline-panel grouped-timeline"><div className="section-heading"><div><h2>项目 → 对话 / 任务 → Agent</h2><p>先按项目文件夹合并，再按 ChatGPT 对话 / Task 合并。左侧是最新时间，越往右越早；点击组标题展开具体 Agent。</p></div><div className="segmented">{[1,6,24].map(h=><button key={h} className={hours===h?'chosen':''} onClick={()=>setHours(h)}>{h}h</button>)}</div></div><div className="global-ruler"><span>PROJECT / CONVERSATION / TASK</span><div>{ticks.map(t=><span key={t}>{clock(t).slice(0,5)}</span>)}</div></div>{projects.length?projects.map(p=>{const collapsed=collapsedProjects[p.project]??false;return <section className="timeline-project" key={p.project}><button className="timeline-project-heading" onClick={()=>setCollapsedProjects(s=>({...s,[p.project]:!collapsed}))}><FolderOpen size={16}/><strong>{p.project}</strong><span>{p.groups.length} 组 · {p.count} Agents</span><ChevronDown size={15} className={collapsed?'collapsed-chevron':''}/></button>{!collapsed&&p.groups.map(g=>{const key=`${p.project}:${g.key}`,expanded=expandedGroups[key]??false;return <div className="timeline-work-group" key={g.key}><div className="global-lane group-summary"><button className="lane-title group-title" onClick={()=>setExpandedGroups(s=>({...s,[key]:!expanded}))}><span>{g.meta.kind==='conversation'?'ChatGPT / Task':g.meta.kind==='unassigned'?'AgentDock · 未归属':'Codex · 本机'}</span><strong>{g.meta.title}</strong><small>{g.agents.length} Agents · 最近 {ago(g.latest,now)} <ChevronDown size={12} className={expanded?'':'collapsed-chevron'}/></small></button><div className="global-track"><div className="grid-lines"/><TimelineBar start={g.start} end={g.end} min={start} max={end} tone={g.agents.some(a=>live.has(a.status))?'green':'gray'} top={20} label={`${g.agents.length} Agents`} reverse/></div></div>{expanded&&g.agents.map(a=><div className="global-lane agent-child-lane" key={a.id}><button className="lane-title" onClick={()=>onSelect(a.id)}><span>{a.binding?.title||(a.source==='AgentDock ACP'?'AgentDock · 未归属':'Codex · 本机')}</span><strong>{a.title}</strong><small><Status status={a.status}/>{short(a.id)}</small></button><div className="global-track" onClick={()=>onSelect(a.id)} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&onSelect(a.id)} aria-label={`查看 ${a.title} 时间线`}><div className="grid-lines"/>{a.acpSessions?.slice(0,2).map(acp=><TimelineBar key={acp.id} start={acp.createdAt||a.turn!.startMs} end={acp.closedAt||(activeTurn(a.turn!.status)?now:null)} min={start} max={end} tone="acp" top={10} label="ACP" reverse/>)}<TimelineBar start={a.turn!.startMs} end={a.turn!.endMs||(activeTurn(a.turn!.status)?now:null)} min={start} max={end} tone={tone(a.status)} top={31} label={`turn · ${duration(a.turn!.durationMs??(now-a.turn!.startMs))}`} reverse/>{a.currentTool&&<TimelineBar start={a.currentTool.startMs} end={now} min={start} max={end} tone="amber" top={51} label={a.currentTool.name} reverse/>}</div></div>)}</div>})}</section>}):<Empty title="这段时间没有可用的 turn 记录">扩大到 24 小时查看较早工作；超过一天的 Agent 已从实时线清理。</Empty>}<div className="footnote">项目和对话/任务默认合并，减少大量 Agent 行造成的噪音；历史记录仍保留在“全部记录”。</div></section>
}
function TimelineBar({start,end,min,max,tone:color,top=0,label='',reverse=false}:{start:number;end:number|null;min:number;max:number;tone:string;top?:number;label?:string;reverse?:boolean}){if(start>max||(end!=null&&end<min))return null;const clippedStart=Math.max(start,min),clippedEnd=end==null?null:Math.min(end,max),left=reverse?Math.max(0,(max-(clippedEnd??clippedStart))/(max-min)*100):Math.max(0,(clippedStart-min)/(max-min)*100),width=end==null?0:Math.max(0,(clippedEnd!-clippedStart)/(max-min)*100);return <div className={`timeline-bar ${color} ${end==null?'point':''}`} style={{left:`${Math.min(left,99.5)}%`,width:end==null?7:`max(3px, ${width}%)`,top}} title={`${stamp(start)} → ${end?stamp(end):'结束时间未知 / 瞬时活动'}`}>{width>9&&label}</div>}

type BoardTask={id:string;title:string;goal:string;project:string;status:string;origin:'monitor-auto'|'agentdock';createdAt:number;updatedAt:number;completedAt:number|null;agentIds:string[]};
function TaskBoard({monitorTasks,nativeTasks,agents,now,onSelect,reaper}:{monitorTasks:MonitorTask[];nativeTasks:Task[];agents:Agent[];now:number;onSelect:(id:string)=>void;reaper?:SourceHealth}){
 const [days,setDays]=useState(30),start=now-days*86400000;
 const automatic:BoardTask[]=monitorTasks.map(t=>({id:t.id,title:t.title,goal:t.goal,project:t.project||'unknown',status:t.status,origin:'monitor-auto',createdAt:t.createdAt,updatedAt:t.updatedAt,completedAt:t.completedAt,agentIds:t.agentIds||[]}));
 const native:BoardTask[]=nativeTasks.map(t=>({id:t.id,title:t.title,goal:t.goal,project:t.project||'unknown',status:t.status,origin:'agentdock',createdAt:t.createdAt,updatedAt:t.updatedAt,completedAt:t.completedAt,agentIds:agents.filter(a=>a.task?.id===t.id).map(a=>a.id)}));
 const all=[...automatic,...native].filter(t=>(t.createdAt||t.updatedAt)>=start).sort((a,b)=>b.createdAt-a.createdAt),projects=[...new Set(all.map(t=>t.project))].sort((a,b)=>Math.max(...all.filter(t=>t.project===b).map(t=>t.createdAt))-Math.max(...all.filter(t=>t.project===a).map(t=>t.createdAt))),ticks=Array.from({length:5},(_,i)=>start+(now-start)*i/4);
 const pos=(at:number)=>Math.max(0,Math.min(99,(at-start)/(now-start)*100)),barWidth=(a:number,b:number)=>Math.max(2,Math.min(100-pos(a),(Math.max(a,b)-a)/(now-start)*100));
 return <div className="task-board-wrap"><section className="panel task-board-summary"><div><span className="eyebrow">LEGACY / NATIVE PLAN VIEW</span><h2>AgentDock 原生计划与历史任务</h2><p>上方 Request 视图是新的主进度层；这里保留 AgentDock 原生 Task 与旧版自动任务时间线，便于查看尚未捕获到 Request 的历史工作。</p></div><div className="task-board-controls"><div className="segmented">{[7,30,90].map(d=><button key={d} className={days===d?'chosen':''} onClick={()=>setDays(d)}>{d}d</button>)}</div><span className={`proof-badge ${reaper?.healthy===false?'':'connected'}`}><Clock size={14}/>24h 自动清理{reaper?.lastSweepAt?` · ${ago(reaper.lastSweepAt,now)}`:''}</span></div></section>{all.length?<section className="panel task-board"><div className="task-board-ruler"><span>PROJECT / TASK</span><div>{ticks.map(t=><span key={t}>{new Date(t).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})}</span>)}</div></div>{projects.map(project=>{const items=all.filter(t=>t.project===project);return <section className="task-project" key={project}><header><FolderOpen size={15}/><strong>{project}</strong><span>{items.length}</span></header>{items.map(t=>{const end=t.status==='active'?now:(t.completedAt||t.updatedAt||t.createdAt),linked=t.agentIds[0];return <div className="task-board-row" key={`${t.origin}:${t.id}`}><button className="task-board-label" disabled={!linked} onClick={()=>linked&&onSelect(linked)}><span className={`task-origin ${t.origin==='monitor-auto'?'auto':'native'}`}>{t.origin==='monitor-auto'?'自动识别':'AgentDock'}</span><strong title={t.title}>{t.title}</strong><small>{t.status==='active'?'进行中':'已完成'} · {t.agentIds.length} Agent · {stamp(t.createdAt)}</small></button><div className="task-board-track"><div className="grid-lines"/><button className={`task-board-bar ${t.status==='active'?'active':'done'} ${t.origin==='monitor-auto'?'auto':'native'}`} style={{left:`${pos(t.createdAt)}%`,width:`${barWidth(t.createdAt,end)}%`}} title={`${t.title}\n${stamp(t.createdAt)} → ${t.status==='active'?'现在':stamp(end)}`} onClick={()=>linked&&onSelect(linked)} disabled={!linked}><span>{t.title}</span></button></div></div>})}</section>})}</section>:<Empty title="这个时间范围内还没有任务">自动任务会在某个 ChatGPT 用户目标实际启动 ACP 时创建；AgentDock 原生 Task 也会继续显示。</Empty>}<p className="footnote">纯查询不会因为在同一 conversation 里就被算成任务。超过 24 小时无活动的 Agent 不再出现在主时间线；有 ACP session 的会由本机清理器调用 AgentDock 的 session close。</p></div>
}

function TaskCard({task,compact:small=false}:{task:Task;compact?:boolean}){const done=task.steps.filter(s=>s.status==='completed').length;return <section className={`task-card ${small?'compact':''}`}><div className="section-heading"><div><span className="eyebrow">{task.phase} · {task.status}</span><h3>{task.title}</h3></div><span className="task-fraction">{done}<small> / {task.steps.length}</small></span></div><div className="task-progress"><i style={{width:`${task.steps.length?done/task.steps.length*100:0}%`}}/></div>{!small&&<p>{task.goal}</p>}<div className="task-steps">{task.steps.map(s=><div className={s.status} key={s.id}>{s.status==='completed'?<CheckCircle2 size={15}/>:s.status==='in_progress'?<span className="step-pulse"/>:<Circle size={15}/>}<span>{s.title}</span></div>)}</div>{!small&&<footer><span>{task.project}</span><time>{stamp(task.updatedAt)}</time></footer>}</section>}

function AgentDetail({agent:a,tasks,now,onClose,onBind,onSelect,onArchive,notify}:{agent:Agent;tasks:Task[];now:number;onClose:()=>void;onBind:()=>void;onSelect:(id:string)=>void;onArchive:(a:Agent,archived:boolean)=>void;notify:Notify}){
 const [tab,setTab]=useState('overview'),[detail,setDetail]=useState<Detail|null>(null),[error,setError]=useState('');
 useEffect(()=>{setTab('overview');setDetail(null);setError('')},[a.id]);
 useEffect(()=>{let alive=true;invoke<Detail>('get_detail',{id:a.id}).then(v=>{if(alive)setDetail(v)}).catch(e=>{if(alive)setError(String(e))});return()=>{alive=false}},[a.id,a.turn?.id,a.lastActivityMs]);
 const elapsed=a.turn?(a.turn.durationMs??(activeTurn(a.turn.status)?now-a.turn.startMs:null)):null;
 let toolTime=0;if(a.turn&&detail){const intervals=detail.events.filter(e=>e.turnId===a.turn?.id&&e.endMs!=null&&['tool','commandExecution','mcpToolCall','fileChange','dynamicToolCall','collabAgentToolCall','webSearch'].includes(e.kind)).map(e=>[Math.max(e.startMs,a.turn!.startMs),Math.min(e.endMs!,a.turn!.endMs||now)]).filter(([s,e])=>e>=s).sort((x,y)=>x[0]-y[0]);let lastEnd=0;for(const[s,e]of intervals){toolTime+=Math.max(0,e-Math.max(s,lastEnd));lastEnd=Math.max(lastEnd,e);}}
 return <aside className="detail-panel"><header><div><span className="eyebrow">LOGICAL AGENT</span><h2>{a.project}</h2></div><IconButton label="关闭详情" onClick={onClose}><X size={20}/></IconButton></header><div className="detail-title"><h3>{a.title}</h3><Status status={a.status}/><span className="detail-source">{a.source}</span></div><nav className="detail-tabs">{[['overview','当前工作'],['timeline','时间线'],['evidence','关系与证据']].map(([v,l])=><button className={tab===v?'selected':''} key={v} onClick={()=>setTab(v)}>{l}</button>)}</nav><div className="detail-content">
 {tab==='overview'&&<><div className="detail-kpis"><div><span>THREAD TOKENS</span><strong>{compact(a.tokensUsed)}</strong><small>{full(a.tokensUsed)} · 累计</small></div><div><span>CURRENT / LAST TURN</span><strong>{duration(elapsed)}</strong><small>{a.turn?.source||'unknown source'}</small></div></div><dl className="facts"><Field label="Model" value={a.model}/><Field label="Provider / reasoning" value={`${a.modelProvider||'unknown'} · ${a.reasoningEffort||'unknown'}`}/><Field label="最后活动" value={ago(a.lastActivityMs,now)}/><Field label="当前工具" value={a.currentTool?.name}/></dl>
 <div className="detail-section"><div className="section-heading"><h3>发起来源</h3><button className="text-button" onClick={onBind}><Link2 size={14}/>{a.binding?'查看 / 绑定':'手动绑定（兜底）'}</button></div>{a.binding?<div className="origin-card"><Command size={21}/><div><strong>{a.binding.title||short(a.binding.conversationId)}</strong><small>{a.binding.source}</small></div><IconButton label="打开 ChatGPT 对话" onClick={()=>action('open_conversation',{url:a.binding!.url},notify,'已打开对话')}><ExternalLink size={16}/></IconButton></div>:<p className="muted">unknown · 没有网页对话归属证据。{a.source==='AgentDock ACP'?'ACP 和 Codex 的后半条链已连接。':''}</p>}</div>
 <div className="detail-section"><div className="section-heading"><h3>语义进度</h3><ListChecks size={16}/></div>{a.task?<TaskCard task={a.task} compact/>:<p className="muted">没有显式关联的 AgentDock task。下面展示实际 turn / 工具活动。</p>}<label className="select-label">显式关联任务<select aria-label="关联 AgentDock task" value={a.task?.id||''} onChange={e=>action('link_task',{threadId:a.id,taskId:e.target.value||null},notify)}><option value="">不关联 task</option>{tasks.map(t=><option key={t.id} value={t.id}>{t.title}</option>)}</select></label></div>
 {a.lastCommand&&<div className="detail-section"><h3><Terminal size={16}/>最近命令</h3><pre className="command-block">{a.lastCommand}</pre><small className="muted">经过常见凭证模式脱敏；不是原始工具输出。</small></div>}{a.lastFile&&<div className="detail-section"><h3><FileCode2 size={16}/>最近文件活动</h3><code className="wrap-code">{a.lastFile}</code></div>}
 {elapsed!=null&&<div className="detail-section"><h3>时间去了哪里</h3><div className="time-breakdown"><div style={{width:`${elapsed?Math.min(100,toolTime/elapsed*100):0}%`}}/></div><dl className="facts"><Field label="已记录工具区间（去重叠）" value={duration(toolTime)}/><Field label="未细分间隔" value={duration(Math.max(0,elapsed-toolTime))}/></dl><p className="fine-print">未细分间隔可能包含模型、网络或缺失的工具记录。时间线可能只覆盖部分历史，不等于全部推理耗时。</p></div>}
 {a.turn?.error&&<div className="notice danger"><AlertTriangle size={16}/><p>{a.turn.error}</p></div>}
 {(a.archived||['SUSPECTED_STALLED','FAILED','CRASHED','WAITING_USER'].includes(a.status))&&<div className="detail-section disposition"><h3><Archive size={16}/>处理这个提醒</h3><p className="fine-print">归档只表示“我已经看过，不需要介入”。Monitor 仍保留真实的 {labels[a.status]||a.status} 证据；如果这个 thread 之后产生新活动，会自动重新进入当前工作。</p><button className="secondary full-width" onClick={()=>onArchive(a,!a.archived)}>{a.archived?<><ArchiveRestore size={15}/>恢复到工作列表</>:<><Archive size={15}/>归档并从“需留意”移除</>}</button></div>}</>}
 {tab==='timeline'&&(error?<div className="notice danger">{error}</div>:detail?<DetailTimeline detail={detail} agent={a} now={now}/>:<Empty title="读取结构化时间线"/>)}
 {tab==='evidence'&&<><div className="evidence-card"><div className="eyebrow">STATUS EVIDENCE</div><Status status={a.status} code/><p className="fine-print">{a.statusConfidence}</p>{a.statusEvidence?.map((r,i)=><p className="evidence-reason" key={i}><i/>{r}</p>)}</div><dl className="facts ids"><Field label="ChatGPT conversation ID" value={a.binding?.conversationId} mono/><Field label="Chat URL" value={a.binding?.url} mono/><Field label="Codex thread ID" value={a.id} mono/><Field label="Current / last turn ID" value={a.turn?.id} mono/><Field label="Workspace" value={a.cwd} mono/><Field label="创建时间" value={stamp(a.createdAt)}/><Field label="最近活动时间" value={stamp(a.lastActivityMs)}/><Field label="Turn 完成时间" value={stamp(a.turn?.endMs)}/><Field label="Token 来源" value={a.tokenSource}/><Field label="Model 来源" value={a.modelSource}/><Field label="Host PID" value={a.hostPid}/><Field label="Host executable" value={a.hostProcess?.exe} mono/><Field label="Host CPU / RAM" value={a.hostProcess?`${a.hostProcess.cpu?.toFixed(1)??'unknown'}% · ${(a.hostProcess.memory/1048576).toFixed(0)} MB`:null}/></dl><p className="fine-print">Host PID 来自 Windows thread-writer-lock 持有者查询。子进程属于共享 host，不能直接声称属于这个 thread。</p>
 {a.acpSessions?.map(s=><section className="acp-evidence" key={s.id}><h3>ACP session</h3><dl className="facts ids"><Field label="ACP ID" value={s.id} mono/><Field label="Remote session / thread" value={s.remoteSessionId} mono/><Field label="AgentDock parent namespace" value={s.parentId} mono/><Field label="Transport status / stop reason" value={`${s.status} / ${s.stopReason||'unknown'}`}/><Field label="Created / closed" value={`${stamp(s.createdAt)} → ${stamp(s.closedAt)}`}/></dl><p className="fine-print">这个 parent 是共享 namespace，不是 ChatGPT conversation ID。closed 仅表示连接关闭。</p></section>)}
 {a.parentThreadId&&<button className="secondary full-width" onClick={()=>onSelect(a.parentThreadId!)}><GitBranch size={16}/>父 thread · {short(a.parentThreadId)}</button>}{a.childThreadIds?.length>0&&<div className="detail-section"><h3>Logical subagents</h3>{a.childThreadIds.map(id=><button className="child-link" key={id} onClick={()=>onSelect(id)}><GitBranch size={14}/><code>{short(id,24)}</code><ChevronRight size={14}/></button>)}</div>}
 {a.childProcesses?.length>0&&<div className="detail-section"><h3>Host 子进程（共享范围）</h3>{a.childProcesses.slice(0,20).map(p=><div className="mini-process" key={p.pid}><span>{p.name}</span><code>{p.pid}</code><span>{(p.memory/1048576).toFixed(0)} MB</span></div>)}</div>}
 {a.sourceWarning&&<div className="notice">{a.sourceWarning}</div>}{a.binding&&<button className="secondary full-width" onClick={()=>{if(window.confirm('移除这条归属证据？由它继承来源的子 Agent 也会恢复为未归属。'))action('unbind_agent',{entityId:a.binding!.entityId},notify,'已移除绑定')}}>移除这条对话绑定</button>}</>}
 </div></aside>
}

function DetailTimeline({detail,agent,now}:{detail:Detail;agent:Agent;now:number}){
 const [filter,setFilter]=useState('tools'),[event,setEvent]=useState<Event|null>(null),[turn,setTurn]=useState(agent.turn?.id||'all');
 const turnIds=[...new Set(detail.events.map(e=>e.turnId).filter((s):s is string=>!!s))];
 const source=detail.events.filter(e=>turn==='all'||e.turnId===turn);
 const shown=source.filter(e=>filter==='all'||!['reasoning','agentMessage','tokens','turn','subAgentActivity','contextCompaction'].includes(e.kind)).slice(-180);
 const min=Math.min(...source.map(e=>e.startMs),agent.turn?.id===turn?agent.turn.startMs:Infinity);const max=Math.max(min+1000,...source.map(e=>e.endMs||e.startMs),activeTurn(agent.turn?.status)&&turn===agent.turn?.id?now:0);
 return <div className="detail-timeline"><div className="segmented"><button className={filter==='tools'?'chosen':''} onClick={()=>setFilter('tools')}>工具活动</button><button className={filter==='all'?'chosen':''} onClick={()=>setFilter('all')}>全部元数据</button></div><label className="select-label">Turn<select aria-label="时间线 turn" value={turn} onChange={e=>{setTurn(e.target.value);setEvent(null)}}><option value="all">全部已覆盖历史</option>{turnIds.map(id=><option value={id} key={id}>{id===agent.turn?.id?'当前 / 最近 · ':''}{short(id,16)}</option>)}</select></label><p className="fine-print">{detail.projectionAvailable?'Structured projection':'Rollout / observation journal'} · {shown.length} 个事件 · 部分历史覆盖</p>{shown.length>0?<><div className="detail-ruler"><span>{clock(min)}</span><span>{clock(max)}</span></div>{shown.map(e=><button className={`event-row ${event?.id===e.id?'selected':''}`} key={e.id} onClick={()=>setEvent(e)}><div><span>{e.name}</span><small>{duration(e.durationMs)} · {e.status}</small></div><div className="event-track"><TimelineBar start={e.startMs} end={e.endMs||(activeTurn(agent.turn?.status)&&activeTurn(e.status)&&e.turnId===agent.turn?.id?now:null)} min={min} max={max} tone={e.status==='failed'?'red':e.kind==='reasoning'?'gray':e.kind==='turn'?'green':'acp'} top={9}/></div></button>)}</>:<Empty title="没有对应的工具事件">模型活动可能仍然存在。选择“全部元数据”或其他 turn。</Empty>}{event&&<div className="selected-event"><div className="section-heading"><h3>{event.name}</h3><IconButton label="关闭事件详情" onClick={()=>setEvent(null)}><X size={15}/></IconButton></div><dl className="facts"><Field label="Status" value={event.status}/><Field label="Start / end" value={`${stamp(event.startMs)} → ${stamp(event.endMs)}`}/><Field label="Duration" value={duration(event.durationMs)}/><Field label="Token delta" value={event.tokenDelta}/><Field label="Source" value={event.source}/><Field label="Tool session handle（不是 OS PID）" value={event.toolSessionId}/></dl>{event.command&&<pre className="command-block">{event.command}</pre>}{event.file&&<code className="wrap-code">{event.file}</code>}</div>}<p className="fine-print">首次 JSONL 读取只覆盖末尾 1 MiB；projection 最多返回最近 4,000 项。菱点表示没有已知持续时间，不会把两次活动之间的空白伪造成 reasoning 时长。</p></div>
}

function ProcessPage({processes,agents}:{processes:Process[];agents:Agent[]}){const [hosts,setHosts]=useState(true),[query,setQuery]=useState(''),[limit,setLimit]=useState(100);const filtered=processes.filter(p=>(!hosts||p.role.includes('host')||p.role==='AgentDock')&&`${p.pid} ${p.name} ${p.exe}`.toLowerCase().includes(query.toLowerCase()));return <section className="panel"><div className="toolbar"><div className="segmented"><button className={hosts?'chosen':''} onClick={()=>setHosts(true)}>Agent hosts</button><button className={!hosts?'chosen':''} onClick={()=>setHosts(false)}>所有关联进程</button></div><label className="search"><Search size={16}/><input aria-label="搜索进程" placeholder="进程、PID、路径…" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="notice"><GitBranch size={18}/><p>同一个 Codex app-server 可以承载多个 logical thread。只有锁持有者查询支持的关系才计入“已关联 threads”。</p></div><div className="table-scroll"><table className="process-table"><thead><tr><th>PROCESS / EXECUTABLE</th><th>PID / PARENT</th><th>THREADS</th><th>CPU</th><th>RAM</th></tr></thead><tbody>{filtered.slice(0,limit).map(p=><tr key={p.pid}><td><strong><Cpu size={15}/>{p.name}<span className="small-tag">{p.role}</span></strong><small title={p.exe||'unknown'}>{p.exe||'unknown executable'}</small></td><td><code>{p.pid}</code><small>↳ {p.parentPid??'unknown'}</small></td><td><span className="count-badge">{agents.filter(a=>a.hostPids?.includes(p.pid)).length||'—'}</span></td><td>{p.cpu==null?'—':`${p.cpu.toFixed(1)}%`}</td><td>{(p.memory/1048576).toFixed(0)} MB</td></tr>)}</tbody></table></div>{filtered.length>limit&&<button className="show-more" onClick={()=>setLimit(l=>l+100)}>显示更多进程</button>}<div className="footnote">{filtered.length} 个匹配进程 · CPU 为系统采样值，多核口径可能超过 100%；不参与“进程已死”的单独判断。</div></section>}

function UsagePage({snapshot,notify}:{snapshot:Snapshot;notify:Notify}){const [days,setDays]=useState(1),[stats,setStats]=useState<Analytics|null>(snapshot.analyticsToday||null);useEffect(()=>{let live=true;invoke<Analytics>('get_analytics',{days}).then(v=>{if(live)setStats(v)}).catch(e=>notify(String(e)));return()=>{live=false}},[days,snapshot.stats?.observedTokensToday]);const group=(title:string,rows:{name:string;tokens:number}[])=>{const max=Math.max(1,...rows.map(r=>r.tokens));return <section className="panel ranking"><h3>{title}</h3>{rows.length?rows.map(r=><div className="ranking-row" key={r.name}><div><span>{r.name||'unknown'}</span><strong>{compact(r.tokens)}</strong></div><i><b style={{width:`${r.tokens/max*100}%`}}/></i></div>):<Empty title="还没有连续观测增量">初次见到的累计 token 只建立基线。Agent 后续产生新用量时，这里才会增长。</Empty>}</section>};return <><div className="toolbar"><div className="segmented">{[[1,'Today'],[7,'Last 7 days'],[30,'Last 30 days']].map(([v,l])=><button key={v} className={days===v?'chosen':''} onClick={()=>setDays(Number(v))}>{l}</button>)}</div><span className="proof-badge"><ShieldCheck size={14}/>不估算账单</span></div><section className="usage-hero"><div><div className="eyebrow">OBSERVED TOKEN DELTA</div><strong>{full(stats?.observedTokens)}</strong><span>从 {stamp(stats?.firstObservedAt)} 开始观测</span></div><p>仅统计连续采样时真实累计值的正增量。首次基线、超过 30 秒的采集间隙、跨日间隙与计数器重置不填补估算值。这不是 ChatGPT 网页本身的 token，也不是订阅账单。</p></section><div className="usage-grid">{group('按模型',stats?.byModel||[])}{group('按项目',stats?.byProject||[])}</div><section className="panel"><div className="section-heading"><h3>最耗 token 的已知工作 · 累计值</h3><span className="small-tag">不是所选日期区间的消耗</span></div>{[...snapshot.agents].filter(a=>a.tokensUsed!=null).sort((a,b)=>(b.tokensUsed||0)-(a.tokensUsed||0)).slice(0,8).map(a=><div className="usage-agent" key={a.id}><div><strong>{a.title}</strong><small>{a.project} · {a.model||'unknown'} · {short(a.id)}</small></div><b>{compact(a.tokensUsed)}</b></div>)}</section><p className="footnote">按 conversation 的历史精确分摊尚未回填：未来绑定不应把 thread 之前的全部消耗追溯算给新的对话。此版优先保存正确、可审计的采样数据。</p></>}

function SettingsPage({snapshot,notify}:{snapshot:Snapshot;notify:Notify}){
 const [setup,setSetup]=useState<{dataDir:string;extensionDir:string;autostart:boolean;remote?:{publicUrl:string;webPort:number}}|null>(null),[key,setKey]=useState('');useEffect(()=>{invoke<typeof setup>('get_setup_info').then(setSetup).catch(e=>notify(String(e)))},[]);
 const copy=async()=>{try{const token=await invoke<string>('get_pairing_token');setKey(token);await navigator.clipboard.writeText(token);notify('配对密钥已复制；只粘贴到 Agent Monitor 扩展，不要发到聊天或 Git。')}catch(e){notify(`自动复制不可用；可以复制下方密钥。${String(e)}`)}};
 const bridge=snapshot.sources?.bridge,backgroundConnected=!!bridge?.lastExtensionSeen,pageObserverConnected=!!bridge?.lastPageObserverSeen&&Date.now()-(bridge.lastPageObserverSeen||0)<90000,automatic=backgroundConnected&&pageObserverConnected,progressPolicy=snapshot.sources?.progressPolicy;
 const prepare=(browser:'chrome'|'edge')=>action('prepare_browser_attribution',{browser},notify,`已打开 ${browser==='chrome'?'Chrome':'Edge'} 扩展页和 Agent Monitor 扩展文件夹`);
 return <div className="settings-grid">{setup?.remote&&<section className="panel remote-desktop-card"><div className="section-heading"><h2>手机与远程网页</h2><span className="proof-badge"><ShieldCheck size={14}/>Cloudflare Access</span></div><p>手机浏览器打开下方地址，登录后查看家里电脑。可以添加到主屏幕。关闭窗口后，托盘中的采集器继续工作。</p><a href={setup.remote.publicUrl} target="_blank" rel="noreferrer">{setup.remote.publicUrl} <ExternalLink size={14}/></a><p className="fine-print">此处显示已配置地址；远程可达性还取决于电脑联网及 Tunnel 是否运行。</p></section>}<section className="panel browser-setup"><div className="section-heading"><div><span className="eyebrow">CHATGPT → LOCAL AGENT</span><h2>ChatGPT 自动归属</h2></div><span className={`proof-badge ${automatic?'connected':''}`}><Wifi size={14}/>{automatic?'页面捕捉已连接':backgroundConnected?'扩展后台已连接 · 页面捕捉未连接':'等待浏览器扩展连接'}</span></div><p>启用一次后，不需要保持扩展弹窗打开。每个 ChatGPT 标签页会把自己的 conversation ID、每条用户消息 ID 与该条消息触发的 AgentDock 工具活动对应起来；普通 read/file/command/task_manage 与 ACP 都可以进入同一 Request。只保存请求文本与必要归属元数据，不复制整个聊天记录或工具输出。</p>{automatic&&<div className="auto-attribution-state"><CheckCircle2 size={18}/><div><strong>ChatGPT 页面捕捉正在运行</strong><small>页面 observer：{stamp(bridge?.lastPageObserverSeen)} · 扩展后台：{stamp(bridge?.lastExtensionSeen)}{bridge?.lastBindingAt?` · 最近自动绑定：${stamp(bridge.lastBindingAt)}`:''}</small></div></div>}{backgroundConnected&&!pageObserverConnected&&<div className="notice"><AlertTriangle size={18}/><p><strong>扩展后台已连接，但 ChatGPT 页面捕捉没有运行。</strong> 重新加载 Agent Monitor 扩展并刷新 ChatGPT 标签页；仅有 heartbeat 不再被显示为自动捕捉正常。</p></div>}<div className="setup-step"><b>1</b><div><h3>一次性加载浏览器扩展</h3><p>选择你实际使用 ChatGPT 的浏览器。软件会同时打开扩展管理页和正确的扩展文件夹；开启“开发者模式”后点“加载已解压的扩展程序”，选择这个文件夹即可。</p><div className="browser-actions"><button className="secondary" onClick={()=>prepare('chrome')}><ExternalLink size={15}/>打开 Chrome 扩展页</button><button className="secondary" onClick={()=>prepare('edge')}><ExternalLink size={15}/>打开 Edge 扩展页</button></div><code className="wrap-code">{setup?.extensionDir||'安装包附带的 extension 目录'}</code></div></div><div className="setup-step"><b>2</b><div><h3>只配对一次</h3><p>打开 Agent Monitor 扩展图标，把这里的密钥粘贴进去并点“配对”。以后启动浏览器或打开 ChatGPT 时，扩展会自动向本机 Monitor 报到，不需要再次打开弹窗。</p><button className="primary" onClick={copy}><Copy size={15}/>复制一次性配对密钥</button>{key&&<div className="pairing-secret"><code>{key}</code><button className="text-button" onClick={()=>setKey('')}>隐藏密钥</button></div>}</div></div><div className="setup-step"><b>3</b><div><h3>刷新已经打开的 ChatGPT 标签页</h3><p>这一步只在首次安装或扩展更新后需要。之后正常使用 ChatGPT：每条用户消息会成为独立 Request；执行型 Request 会关联 task_manage 的步骤、普通 AgentDock 工具以及可选 ACP / Codex Agent。运行中新增的补充计划段会实时并入同一 Request。</p></div></div><div className="notice"><AlertTriangle size={18}/><p><strong>边界：</strong>扩展只观察安装它的电脑浏览器。普通 AgentDock 工具归属依赖同一 ChatGPT turn 中的结构化调用/结果；ACP 归属仍只接受确切 ACP ID。手机 ChatGPT、未暴露结构化工具消息的调用或旧历史不会靠时间、项目目录或共享 parent 猜测。</p></div></section><section className="panel progress-policy-card"><div className="section-heading"><div><span className="eyebrow">AGENTDOCK USER SKILL</span><h2>全局执行进度规则</h2></div><span className={`proof-badge ${progressPolicy?.healthy?'connected':''}`}><ListChecks size={14}/>{progressPolicy?.healthy?`已激活 ${progressPolicy.activeVersion||''}`:'未激活'}</span></div><p>规则以用户级 <code>execution-progress</code> Skill 安装在 <code>~/.agentdock</code>，不修改 AgentDock 程序目录。执行型请求需要创建 task_manage 计划并持续 checkpoint；运行中发现额外工作时，新建“补充”计划段并实时并入同一 Request。</p><p className="fine-print">本机可读镜像：<code>~/.agentdock/policies/global-execution.md</code>。AgentDock 更新程序文件时不会依赖修改 bin 目录来保留这套规则；Monitor 会持续显示当前激活状态。</p></section><section className="panel"><h3>真实数据源</h3>{[['acp','AgentDock ACP sessions'],['codex','Codex metadata'],['history','Turn / item projection'],['locks','Windows lock ownership'],['agentdock','AgentDock health'],['bridge','Local attribution bridge'],['progressPolicy','Execution progress policy'],['autoStop','24h stale cleanup']].map(([id,title])=>{const s=snapshot.sources?.[id];return <div className="source-row" key={id}><div><strong>{title}</strong><small>{s?.path||s?.error||(id==='autoStop'?`24h inactivity · last ${stamp(s?.lastSweepAt)} · closed ${s?.closedSessions??0} · expired local ${s?.expiredLocalThreads??0}`:id==='bridge'?`127.0.0.1:${s?.port||43217}`:id==='progressPolicy'?`execution-progress ${s?.activeVersion||'not active'} · ~/.agentdock/policies/global-execution.md`:s?.count!=null?`${s.count} records`:id==='locks'?`${s?.mappedThreads??0} mapped threads`:'read-only / local')}</small></div><span className={`source-dot ${s?.healthy?'good':'bad'}`}>{s?.healthy?'Connected':s?.healthy===false?'Degraded':'Unknown'}</span></div>})}</section><section className="panel"><h3>桌面偏好</h3><label className="preference-row"><div><strong>登录 Windows 时启动</strong><small>仅当前 Windows 用户；默认不开启。</small></div><input type="checkbox" checked={setup?.autostart||false} onChange={e=>{const enabled=e.target.checked;invoke('set_autostart',{enabled}).then(()=>{setSetup(s=>s?{...s,autostart:enabled}:s);notify(enabled?'已开启登录启动':'已关闭登录启动')}).catch(e=>notify(String(e)))}}/></label><div className="preference-row"><div><strong>关闭窗口后留在系统托盘</strong><small>右键托盘图标 → Quit Agent Monitor，才会退出采集器。</small></div><Check size={17}/></div><div className="preference-row"><div><strong>Monitor 自有数据</strong><small>{setup?.dataDir||snapshot.settings?.dataDir}</small></div><IconButton label="打开本机数据目录" onClick={()=>action('open_data_dir',{},notify,'已打开数据目录')}><FolderOpen size={17}/></IconButton></div><button className="secondary" onClick={()=>invoke<string>('export_diagnostics').then(p=>notify(`诊断文件已保存：${p}`)).catch(e=>notify(String(e)))}><Download size={15}/>导出不含私密内容的诊断信息</button></section><section className="panel"><h3>不会做的推断</h3><div className="principle"><ShieldCheck size={18}/><p>PID ≠ Agent；closed ≠ 成功；CPU = 0 ≠ 死亡；共享 parent / 同项目 / 时间接近 ≠ 同一个 ChatGPT 对话。</p></div><p className="fine-print">采集源仍按只读方式读取。唯一的自动控制动作是：逻辑 Agent 超过 24 小时没有活动时，若存在 AgentDock ACP session，就调用 AgentDock 自己的 session close；Codex-only 旧记录只从实时视图过期，不杀共享 host PID。没有任意命令、重启或业务项目修改入口。</p></section></div>
}

function BindModal({agent,onClose,notify}:{agent:Agent;onClose:()=>void;notify:Notify}){const [entity,setEntity]=useState(agent.acpSessions?.[0]?.id||agent.id),[url,setUrl]=useState(agent.binding?.url||''),[title,setTitle]=useState(agent.binding?.title||''),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await invoke('bind_agent',{input:{entityId:entity,conversationUrl:url.trim(),title:title.trim()}});notify('已保存显式绑定；其他不相关 ACP 不会被一起归属。');onClose()}catch(e){setError(String(e))}finally{setBusy(false)}}return <div className="modal-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="bind-title"><header><div><span className="eyebrow">EXPLICIT ATTRIBUTION</span><h2 id="bind-title">绑定网页对话</h2></div><IconButton label="关闭绑定窗口" onClick={onClose}><X size={19}/></IconButton></header><p>将确切的运行与它的发起对话关联。不会把共享 AgentDock parent 目录里的其他运行一起绑定。</p><form onSubmit={submit}><label className="form-label">绑定范围<select aria-label="绑定范围" value={entity} onChange={e=>setEntity(e.target.value)}>{agent.acpSessions?.map(s=><option value={s.id} key={s.id}>ACP · {s.id}</option>)}<option value={agent.id}>整个 logical thread · {short(agent.id,16)}</option></select></label><label className="form-label">ChatGPT 对话 URL<input autoFocus type="url" required placeholder="https://chatgpt.com/c/…" value={url} onChange={e=>setUrl(e.target.value)}/></label><label className="form-label">对话标题（可选；未知时留空）<input maxLength={250} placeholder="例如：接手后端工作" value={title} onChange={e=>setTitle(e.target.value)}/></label>{error&&<div className="form-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>取消</button><button className="primary" disabled={busy} type="submit"><Link2 size={15}/>{busy?'保存中…':'保存明确绑定'}</button></div></form></section></div>}

class ErrorBoundary extends React.Component<{children:React.ReactNode},{error:string}>{state={error:''};static getDerivedStateFromError(e:Error){return {error:e.message}}render(){return this.state.error?<div className="fatal-error"><h1>Agent Monitor 遇到界面错误</h1><p>{this.state.error}</p><button onClick={()=>location.reload()}>重新加载界面</button><p>源数据不会被修改。可在数据目录检查诊断或重新启动应用。</p></div>:this.props.children}}
createRoot(document.getElementById('root')!).render(<ErrorBoundary><App/></ErrorBoundary>);

if(!desktop&&'serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{})});}
